r"},{["id"]=5462,["title"]="The Dying, Ras Frostwhisper"}},["start"]="Leonid Barthalomew the Revered, Light's Hope Chapel, Eastern Plaguelands",["title"]="Menethil's Gift"},[5464]={["start"]="Menethil's Gift",["title"]="Menethil's Gift"},[5465]={["start"]="Leonid Barthalomew the Revered, Eastern Plaguelands",["title"]="Soulbound Keepsake"},[5466]={["class"]=nil,["finish"]="Magistrate Marduke, Caer Darrow, Western Plaguelands",["objective"]="Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.",["prereqs"]={{["id"]=5382,["title"]="Doctor Theolen Krastinov, the Butcher"},{["id"]=5515,["title"]="Krastinov's Bag of Horrors"},{["id"]=5384,["title"]="Kirtonos the Herald"},{["id"]=5461,["title"]="The Human, Ras Frostwhisper"},{["id"]=5462,["title"]="The Dying, Ras Frostwhisper"},{["id"]=5463,["title"]="Menethil's Gift"},{["id"]=5464,["title"]="Menethil's Gift"},{["id"]=5465,["title"]="Soulbound Keepsake"}},["start"]="Magistrate Marduke, Caer Darrow, Western Plaguelands",["title"]="The Lich, Ras Frostwhisper"},[5515]={["class"]=nil,["finish"]="Eva Sarkhoff, Caer Darrow, Western Plaguelands",["objective"]="Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.",["prereqs"]={{["id"]=5382,["title"]="Doctor Theolen Krastinov, the Butcher"}},["start"]="Eva Sarkhoff, Caer Darrow, Western Plaguelands",["title"]="Krastinov's Bag of Horrors"},[5518]={["class"]=nil,["finish"]="Knot Thimblejack, Dire Maul",["objective"]="Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul.",["prereqs"]={},["start"]="Knot Thimblejack, Dire Maul",["title"]="The Gordok Ogre Suit"},[5522]={["start"]="T